package project.init.account.service.impl;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import project.init.account.domain.entity.AccountInfo;import project.init.account.repository.AccountInfoRepository;import project.init.account.service.AccountInfoService;@Service@RequiredArgsConstructorpublic class AccountInfoServiceImpl implements AccountInfoService {    private final AccountInfoRepository accountInfoRepository;    @Override    public AccountInfo findByAccountEmail(String email) {        return accountInfoRepository.findByAccountEmail(email).orElse(null);    }    @Override    public void save(AccountInfo accountInfo) {        accountInfoRepository.save(accountInfo);    }}